import csv
import math


def column_mean(file_path: str, column_name: str) -> float:
    """Return the mean of a numeric CSV column, ignoring missing values."""
    values = []

    with open(file_path, "r", newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)

        if not reader.fieldnames or column_name not in reader.fieldnames:
            raise ValueError(f"Column {column_name!r} not found")

        for row in reader:
            raw_value = row.get(column_name, "").strip()

            if not raw_value:
                continue

            try:
                value = float(raw_value)
            except ValueError:
                continue

            if not math.isnan(value):
                values.append(value)

    if not values:
        raise ValueError(f"Column {column_name!r} contains no numeric values")

    return sum(values) / len(values)
