import csv
from math import fsum


def mean_csv_column(file_path: str, column: str) -> float:
    """Return the mean of a numeric CSV column, ignoring missing values."""
    missing_values = {"", "na", "n/a", "null", "none"}
    values = []

    with open(file_path, newline="", encoding="utf-8-sig") as file:
        reader = csv.DictReader(file)

        if not reader.fieldnames or column not in reader.fieldnames:
            raise KeyError(f"Column {column!r} not found")

        for line_number, row in enumerate(reader, start=2):
            value = (row.get(column) or "").strip()

            if value.lower() in missing_values:
                continue

            try:
                values.append(float(value))
            except ValueError as exc:
                raise ValueError(
                    f"Invalid numeric value {value!r} on line {line_number}"
                ) from exc

    if not values:
        raise ValueError(f"Column {column!r} contains no numeric values")

    return fsum(values) / len(values)
```

